class Solution {
  public int getMoneyAmount(int n) {
    int[][] dp = new int[n + 2][n + 2]; // dp[l][r]: money needed to guarantee a win in [l, r]
    for (int len = 2; len <= n; len++)
      for (int l = 1; l + len - 1 <= n; l++) {
        int r = l + len - 1;
        dp[l][r] = Integer.MAX_VALUE;
        for (int g = l; g <= r; g++) dp[l][r] = Math.min(dp[l][r], g + Math.max(dp[l][g - 1], dp[g + 1][r]));
      }
    return dp[1][n];
  }
}
